export function evaluate({ inputs, time }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = 9.8;
  const t = time;
  const velocity = launchSpeed - gravity * t;
  const height = launchSpeed * t - 0.5 * gravity * t * t;

  let motionStateText = "Moving up";
  if (Math.abs(velocity) < 0.05) {
    motionStateText = "Still for an instant";
  } else if (velocity < 0) {
    motionStateText = "Moving down";
  }

  const gravityStateText = "Gravity pulls down";

  const objects = [];

  // Panel lane
  objects.push(sdk.panel({
    x: 40,
    y: 40,
    w: 560,
    h: 340,
    title: "Vertical Toss",
    state: motionStateText
  }));

  // Axis
  objects.push(sdk.axis("axis.height", {
    x: 100,
    y: 320,
    length: 220,
    orientation: "y",
    min: 0,
    max: 2.5,
    ticks: [0, 0.5, 1.0, 1.5, 2.0, 2.5],
    label: "Height",
    unit: "m"
  }));

  // Ground mark & height guide
  objects.push(sdk.groundMark("ground", 220, 320, 120, "Launch mark"));

  // Ball position calculation (mapping height to screen y: y decreases as height increases)
  // scale: 80 pixels per meter
  const baseY = 320;
  const pxPerMeter = 80;
  const ballY = baseY - height * pxPerMeter;
  const ballX = 220;

  if (height >= 0) {
    objects.push(sdk.circle("ball.toss", ballX, ballY, 28, {
      role: "observed"
    }));
  }

  // Motion arrow (velocity)
  if (Math.abs(velocity) >= 0.05) {
    const dir = velocity > 0 ? "up" : "down";
    objects.push(sdk.vector("vec.v", {
      x: ballX + 25,
      y: ballY
    }, {
      value: Math.abs(velocity),
      direction: dir
    }, {
      scale: 15,
      minLength: 12,
      label: "v",
      role: "observed"
    }));
  }

  // Gravity arrow (constant acceleration down)
  objects.push(sdk.vector("vec.a", {
    x: ballX - 35,
    y: ballY
  }, {
    value: gravity,
    direction: "down"
  }, {
    scale: 5,
    minLength: 12,
    label: "a",
    role: "prediction"
  }));

  // Callout next to the ball
  const calloutLines = [
    motionStateText,
    gravityStateText
  ];
  objects.push(sdk.callout(ballX + 55, ballY - 20, calloutLines, {
    id: "callout.toss"
  }));

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "motionState", value: motionStateText },
        { id: "gravityState", value: gravityStateText }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      velocity,
      height,
      apexTime: launchSpeed / gravity,
      apexHeight: (launchSpeed * launchSpeed) / (2 * gravity)
    }
  };
}
